// Des: Tests cloud DB purge: ledger, blank bodies, drop rows
// Flo: temp db with page + reco + ledger rows > run the ladder against a mock cloud SQL > assert statements and ledger
// I/O: mock cloud + temp db > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const dbzz = @import("ru-purg-dbzz.zig"); const sync = @import("sy-clou-sync.zig"); const cmok = @import("sy-clou-mock.zig"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig"); const hash = @import("ut-hash-dedu.zig");
const allo = std.testing.allocator;
const NOWZ: i64 = 1795528470301;
const DAYZ: i64 = 86400000;
const Rigg = struct { tmpz: std.testing.TmpDir, cldz: cmok.Mock, dirz: []u8, dbzz: sqli.Dbzz, aren: std.heap.ArenaAllocator, synz: sync.Sync,
pub fn upzz(self: *Rigg) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); self.cldz = cmok.Mock.init(allo); self.synz = .{ .iozz = std.testing.io, .dbzz = &self.dbzz, .dirz = self.dirz, .conf = .{}, .store = self.cldz.store(), .sql2 = self.cldz.sql2() }; self.synz.conf.purg_maxx_pctz = 100; }
pub fn down(self: *Rigg) void { self.cldz.deinit(); self.aren.deinit(); self.dbzz.close(); allo.free(self.dirz); self.tmpz.cleanup(); }
pub fn rowzAddz(self: *Rigg, urlz: []const u8, code: i64, fetc: i64, timz: i64, byts: i64) !void { try inde.pageSetz(&self.dbzz, urlz, .{ .hexz = "h", .etag = "", .lmod = "", .code = code, .tier = 1, .vend = "", .fetc = fetc, .next = 2 }); try inde.recoSetz(&self.dbzz, urlz, .{ .hexz = "h", .kind = "text", .body = "b" }, timz); try sync.ledgSetz(&self.dbzz, &hash.hashHexz(urlz), byts); }
pub fn urlzOfzz(self: *Rigg, indx: usize) ![]const u8 { return std.fmt.allocPrint(self.aren.allocator(), "http://a/{d}", .{indx}); }
pub fn ledg(self: *Rigg, urlz: []const u8) !i64 { var stmt = try self.dbzz.prep("SELECT byts FROM dbcl WHERE urlh=?1;"); defer stmt.fini(); try stmt.bindText(1, &hash.hashHexz(urlz)); if (!try stmt.step()) return -1; return stmt.colzIntz(0); }
pub fn capzOfzz(self: *Rigg, pctz: u64) !u64 { return (try dbzz.dbzzUsed(&self.dbzz)) * 100 / pctz; } };
test "the estimate is the ledger sum plus 30 percent overhead" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.rowzAddz("http://a/x", 200, NOWZ, NOWZ, 1000); try std.testing.expectEqual(@as(u64, 1300), try dbzz.dbzzUsed(&rig3.dbzz)); }
test "below the high mark nothing is sent" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); for (0..4) |indx| try rig3.rowzAddz(try rig3.urlzOfzz(indx), 200, NOWZ, NOWZ - 100 * DAYZ, 10000); const rslt = try dbzz.dbzzRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, try rig3.capzOfzz(50)); try std.testing.expectEqual(dbzz.Actd.none, rslt.act2); try std.testing.expectEqual(@as(usize, 0), rig3.cldz.stm2.items.len); }
test "step 1 blanks bodies older than 30 days, keeps young ones, updates the ledger" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); for (0..6) |indx| try rig3.rowzAddz(try rig3.urlzOfzz(indx), 200, NOWZ, NOWZ - 100 * DAYZ, 10000); for (6..10) |indx| try rig3.rowzAddz(try rig3.urlzOfzz(indx), 200, NOWZ, NOWZ - DAYZ, 10000); const rslt = try dbzz.dbzzRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, try rig3.capzOfzz(90)); try std.testing.expectEqual(dbzz.Actd.purged, rslt.act2); try std.testing.expectEqual(@as(u32, 6), rslt.blan); try std.testing.expectEqual(@as(u32, 0), rslt.gone); try std.testing.expectEqual(@as(usize, 1), rig3.cldz.sawzStmt("UPDATE cl_reco SET body=''")); try std.testing.expectEqual(@as(i64, 400), try rig3.ledg("http://a/0")); try std.testing.expectEqual(@as(i64, 400), try rig3.ledg("http://a/5")); try std.testing.expectEqual(@as(i64, 10000), try rig3.ledg("http://a/6")); const agai = try dbzz.dbzzRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, try rig3.capzOfzz(90)); try std.testing.expectEqual(@as(u32, 0), agai.blan); }
test "step 2 deletes gone rows older than 90 days when blanking is not enough; fresh gone rows stay" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); for (0..3) |indx| try rig3.rowzAddz(try rig3.urlzOfzz(indx), 404, NOWZ - 100 * DAYZ, NOWZ - DAYZ, 10000); try rig3.rowzAddz("http://a/fresh", 410, NOWZ - 5 * DAYZ, NOWZ - DAYZ, 10000); for (4..8) |indx| try rig3.rowzAddz(try rig3.urlzOfzz(indx), 200, NOWZ, NOWZ - DAYZ, 10000); const rslt = try dbzz.dbzzRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, try rig3.capzOfzz(90)); try std.testing.expectEqual(@as(u32, 0), rslt.blan); try std.testing.expectEqual(@as(u32, 3), rslt.gone); try std.testing.expectEqual(@as(usize, 1), rig3.cldz.sawzStmt("DELETE FROM cl_page")); try std.testing.expectEqual(@as(usize, 1), rig3.cldz.sawzStmt("DELETE FROM cl_reco")); try std.testing.expectEqual(@as(i64, -1), try rig3.ledg("http://a/0")); try std.testing.expectEqual(@as(i64, 10000), try rig3.ledg("http://a/fresh")); try std.testing.expectEqual(@as(i64, 10000), try rig3.ledg("http://a/4")); }
test "still above the high mark after both steps: alert, nothing else is deleted" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); for (0..6) |indx| try rig3.rowzAddz(try rig3.urlzOfzz(indx), 200, NOWZ, NOWZ - DAYZ, 10000); const rslt = try dbzz.dbzzRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, try rig3.capzOfzz(95)); try std.testing.expectEqual(dbzz.Actd.alert, rslt.act2); try std.testing.expectEqual(@as(usize, 0), rig3.cldz.stm2.items.len); }
test "the breaker: one run reclaims at most purg_maxx_pctz of the cap, then says limited; the next run continues" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); for (0..300) |indx| try rig3.rowzAddz(try rig3.urlzOfzz(indx), 200, NOWZ, NOWZ - 100 * DAYZ, 10000); rig3.synz.conf.purg_maxx_pctz = 10; const capz = try rig3.capzOfzz(110); const rsl1 = try dbzz.dbzzRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, capz); try std.testing.expectEqual(@as(u32, 50), rsl1.blan); try std.testing.expect(rsl1.limd); const rsl2 = try dbzz.dbzzRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, capz); try std.testing.expectEqual(@as(u32, 50), rsl2.blan); }
test "mode upgr only reports" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); for (0..6) |indx| try rig3.rowzAddz(try rig3.urlzOfzz(indx), 200, NOWZ, NOWZ - 100 * DAYZ, 10000); rig3.synz.conf.clou_poli_mode = "upgr"; const rslt = try dbzz.dbzzRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, try rig3.capzOfzz(90)); try std.testing.expectEqual(dbzz.Actd.upgr, rslt.act2); try std.testing.expectEqual(@as(usize, 0), rig3.cldz.stm2.items.len); try std.testing.expectEqual(@as(i64, 10000), try rig3.ledg("http://a/0")); }
test "dry run counts the plan and changes nothing" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); for (0..6) |indx| try rig3.rowzAddz(try rig3.urlzOfzz(indx), 200, NOWZ, NOWZ - 100 * DAYZ, 10000); rig3.synz.dryz = true; const rslt = try dbzz.dbzzRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, try rig3.capzOfzz(90)); try std.testing.expect(rslt.plan); try std.testing.expectEqual(@as(u32, 6), rslt.blan); try std.testing.expectEqual(@as(usize, 0), rig3.cldz.stm2.items.len); try std.testing.expectEqual(@as(i64, 10000), try rig3.ledg("http://a/0")); }
test "if the cloud SQL is down the ledger is not touched" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); for (0..6) |indx| try rig3.rowzAddz(try rig3.urlzOfzz(indx), 200, NOWZ, NOWZ - 100 * DAYZ, 10000); rig3.cldz.sqlo = true; try std.testing.expectError(error.CloudSql, dbzz.dbzzRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, try rig3.capzOfzz(90))); try std.testing.expectEqual(@as(i64, 10000), try rig3.ledg("http://a/0")); }
// =======================___THIS_IS_THE_END___=======================
